operations:
/* Shared controls */
.button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:10px 18px;border-radius:10px;border:1px solid var(--line);background:var(--surface);font-size:16px;font-weight:500;line-height:1.2;white-space:nowrap;transition:transform .12s var(--ease),background-color .15s,border-color .15s,color .15s}
.button.primary{min-height:48px;background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}
.button:active:not(:disabled),.icon-button:active,.page-nav button:active:not(:disabled),.feedback button:active{transform:scale(.97)}
.text-button{display:inline-flex;align-items:center;min-height:44px;padding:8px 4px;font-size:16px;color:var(--ink-2);text-decoration:underline;text-underline-offset:4px;text-decoration-color:var(--line-strong);transition:color .15s}
.icon-button{display:grid;place-items:center;width:44px;height:44px;border-radius:10px;color:var(--ink-2);transition:transform .12s var(--ease),background-color .15s,color .15s}
@media(hover:hover) and (pointer:fine){.button:hover:not(:disabled){background:var(--surface-2);border-color:var(--line-strong)}.button.primary:hover:not(:disabled){background:var(--accent-hover);border-color:var(--accent-hover)}.text-button:hover,.back-link:hover{color:var(--ink)}.icon-button:hover{background:var(--surface-2);color:var(--ink)}}
.chip{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:500;line-height:1.2;padding:5px 10px;border-radius:999px;background:var(--surface-2);color:var(--ink-2);white-space:nowrap}
.chip.info{background:var(--info-soft);color:var(--info)}.chip.ai{background:var(--ai-soft);color:var(--ai)}.chip.warn{background:var(--warn-soft);color:var(--warn)}
.status{display:inline-flex;align-items:center;gap:7px;font-size:14px;font-weight:500;line-height:1.2;padding:6px 12px;border-radius:999px;background:var(--accent-soft);color:var(--accent);white-space:nowrap}
.status i{width:8px;height:8px;border-radius:50%;background:currentColor}
.status.pending{background:var(--surface-2);color:var(--ink-2)}.status.review{background:var(--warn-soft);color:var(--warn)}.status.failed{background:var(--danger-soft);color:var(--danger)}

/* Prototype review bar (not product UI) */
.review-bar{height:56px;position:sticky;top:0;z-index:20;background:#232423;color:#c5c6c1;border-bottom:1px solid #111;display:flex;align-items:center;gap:20px;padding:0 22px;overflow-x:auto;white-space:nowrap;font-size:13px}
.review-label{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#92958d}.review-group{display:flex;gap:9px;align-items:center}
.review-tabs,.review-themes{display:flex;align-items:center;gap:3px;padding:4px;background:#333532;border-radius:8px}
.review-bar button{font-size:13px;color:#b5b9af;padding:7px 11px;border-radius:5px;white-space:nowrap}
.review-bar button[aria-selected=true],.review-bar button[aria-pressed=true]{background:#f7f8f4;color:#20251d}
.review-bar button:hover:not([aria-selected=true]):not([aria-pressed=true]){color:#fff;background:#ffffff0d}
.review-bar select{border:0;border-radius:6px;background:#333532;color:#e2e5dc;padding:8px 11px;cursor:pointer}.review-spacer{flex:1}
.app-frame{width:min(100%,var(--frame-width,100%));margin:0 auto;min-height:calc(100svh - 56px);container-type:inline-size;container-name:dashboard;background:var(--bg)}
body.narrow-preview{background:#dfe1da}body.dark.narrow-preview{background:#0c0e0c}.narrow-preview .app-frame{box-shadow:0 0 0 1px #80887435,0 12px 80px #10190e20}
@media(max-width:740px){.review-bar{height:52px;padding:0 12px;gap:16px}.review-bar button{padding:7px 9px;font-size:12px}.review-spacer{display:none}.app-frame{min-height:calc(100svh - 52px)}}

/* Header */
.app-frame>header{height:64px;border-bottom:1px solid var(--line);background:var(--surface)}
.header-inner{max-width:760px;margin:auto;padding:0 24px;height:100%;display:flex;align-items:center}
.document-view .header-inner{max-width:1240px}
.brand-logo{display:block;width:140px;height:auto}.brand-logo-dark{display:none}.dark .brand-logo-light{display:none}.dark .brand-logo-dark{display:block}

/* Dashboard */
#dashboard-page{max-width:760px;margin:0 auto;padding:56px 24px 64px}
.intro{margin-bottom:32px}
.sky{display:flex;align-items:center;gap:10px;font-size:16px;font-weight:500;color:var(--accent);margin-bottom:16px}
.sky-avatar{display:grid;place-items:center;width:36px;height:36px;border-radius:50%;background:var(--accent-soft)}.sky-avatar svg{width:22px;height:22px;fill:currentColor;stroke:none}
h1{font-size:40px;line-height:1.12;font-weight:600;letter-spacing:-.02em;text-wrap:balance}
.intro p{font-size:18px;line-height:1.55;color:var(--ink-2);margin-top:12px;max-width:56ch;text-wrap:pretty}
.jumble{display:inline-block;white-space:nowrap}.jumble span{display:inline-block;animation:settle .6s var(--ease) both;animation-delay:calc(var(--i) * 30ms + 150ms)}
@keyframes settle{from{transform:translate(var(--x),var(--y)) rotate(var(--r))}}
.dropzone{position:relative;display:grid;grid-template-columns:156px minmax(0,1fr);gap:32px;align-items:center;padding:32px;border:2px dashed var(--line-strong);border-radius:20px;background:var(--surface);cursor:pointer;transition:border-color .15s,background-color .15s}
.drop-example{margin:0}.drop-example figcaption{font-size:12px;line-height:1.4;color:var(--ink-2);text-align:center;margin-top:10px}
.drop-copy h2{font-size:22px;font-weight:600;line-height:1.3}.drop-copy p{font-size:14px;color:var(--ink-2);margin-top:6px}
.drop-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:20px}
.dropzone.dragging{border-style:solid;border-color:var(--accent);background:var(--accent-soft)}
.dropzone.dragging:after{content:'Drop your PDF here';position:absolute;inset:8px;border-radius:14px;background:var(--accent-soft);display:grid;place-items:center;color:var(--accent);font-size:22px;font-weight:600;pointer-events:none}
.how{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;list-style:none;padding:0;margin:24px 0 0;counter-reset:how}
.how li{display:flex;gap:12px;align-items:flex-start;font-size:14px;line-height:1.45;color:var(--ink-2)}
.how li:before{counter-increment:how;content:counter(how);flex:none;display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--accent-soft);color:var(--accent);font-size:14px;font-weight:600}
.how b{display:block;color:var(--ink);font-size:16px;font-weight:600;margin-bottom:2px}
.message{margin-top:16px;padding:14px 16px;border-radius:12px;background:var(--accent-soft);color:var(--accent);font-size:16px;overflow-wrap:anywhere}.message.error{background:var(--danger-soft);color:var(--danger)}
.list-heading{margin-bottom:12px}.list-heading h2{font-size:14px;font-weight:500;color:var(--ink-2)}.list-heading h2:empty{display:none}
.prototype-note{font-size:14px;line-height:1.55;color:var(--ink-2);margin-top:24px}

/* Document cards */
.job-card{background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:28px;box-shadow:var(--shadow-card);transition:opacity .22s var(--ease),transform .22s var(--ease)}
@starting-style{.job-card{opacity:0;transform:translateY(6px)}}
.job-card+.job-card{margin-top:12px}
.job-heading{display:flex;align-items:center;gap:16px}.job-heading>div:nth-child(2){flex:1;min-width:0}
.document-icon{display:grid;place-items:center;flex:none;width:44px;height:52px;border-radius:10px;background:var(--accent-soft);color:var(--accent)}.document-icon svg{width:24px;height:28px}
.document-name{font-size:20px;font-weight:600;line-height:1.3;overflow-wrap:anywhere}
.document-meta{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:14px;color:var(--ink-2);margin-top:6px}
.job-main{margin-top:24px;padding-top:24px;border-top:1px solid var(--line)}
.job-main h3,#stage-label{font-size:24px;line-height:1.3;font-weight:600;letter-spacing:-.01em}
.job-main p,#stage-detail{font-size:16px;color:var(--ink-2);margin-top:6px}
.job-actions{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-top:24px}.job-actions .text-button{margin-left:auto}
.failed-band{display:flex;gap:14px;align-items:flex-start;padding:20px;border-radius:12px;background:var(--danger-soft);color:var(--danger)}.failed-band svg{width:24px;height:24px;margin-top:3px}.failed-band h3{color:var(--danger)}.failed-band p{color:var(--ink)}
.processing-body{display:grid;grid-template-columns:184px minmax(0,1fr);gap:32px;align-items:start}
#stage-label:focus{outline:none}
.progress-meta{display:flex;justify-content:space-between;gap:12px;font-size:14px;color:var(--ink-2);margin:20px 0 8px;font-variant-numeric:tabular-nums}
.progress{height:8px;background:var(--surface-2);border-radius:999px;overflow:hidden}.progress div{height:100%;background:var(--accent);border-radius:inherit;transform-origin:left;transition:transform .12s linear}
.stage-list{list-style:none;padding:0;margin:20px 0 0;display:grid;gap:2px}
.stage-list li{display:flex;align-items:center;gap:12px;min-height:36px;font-size:16px;color:var(--ink-2)}
.stage-marker{position:relative;display:grid;place-items:center;flex:none;width:24px;height:24px;border-radius:50%;border:2px solid var(--line-strong);font-size:12px;font-weight:600;line-height:1}
.stage-list li[data-phase=active]{color:var(--ink);font-weight:600}
.stage-list li[data-phase=active] .stage-marker{border-color:var(--accent-soft);border-top-color:var(--accent);animation:spin .8s linear infinite}
.stage-list li[data-phase=done]{color:var(--ink)}
.stage-list li[data-phase=done] .stage-marker{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}
.stage-marker svg{width:14px;height:14px;stroke-width:2.6;stroke-dasharray:24;animation:draw .25s var(--ease)}
@keyframes spin{to{transform:rotate(1turn)}}@keyframes draw{from{stroke-dashoffset:24}}
.completion-facts{list-style:none;display:flex;flex-wrap:wrap;gap:12px 24px;margin:24px 0 0;padding:24px 0 0;border-top:1px solid var(--line);font-size:16px}
.completion-facts li{display:flex;align-items:center;gap:8px;animation:rise .2s var(--ease) both;animation-delay:calc(var(--i) * 40ms + 120ms)}.completion-facts svg{color:var(--accent);stroke-width:2.2}
@keyframes rise{from{opacity:0;transform:translateY(4px)}}

/* Mini page: the before/after illustration */
.mini-page{position:relative;width:100%;max-width:184px;aspect-ratio:3/4;margin:0 auto;padding:16px 14px;border-radius:10px;background:#fffdf8;color:#1f2620;box-shadow:0 0 0 1px #00000014,0 12px 28px -10px #141e1450;overflow:hidden;transition:transform .5s var(--ease),box-shadow .5s var(--ease)}
.mp-title{height:8px;width:72%;border-radius:4px;background:#b9b4a6;transform:translate(10px,3px) rotate(-3deg);transition:transform .7s var(--ease),background-color .4s}
.mp-text{display:grid;grid-template-columns:1fr 1fr;gap:6px 8px;margin-top:12px;transition:grid-template-columns .7s var(--ease)}
.mp-text i{display:block;height:5px;width:var(--w);border-radius:3px;background:#d3cec1;transform:translate(var(--dx),var(--dy)) rotate(var(--r));transition:transform .7s var(--ease)}
.mp-eq{position:relative;height:24px;margin:12px 0 10px;font:14px/24px var(--serif)}
.mp-eq span{position:absolute;inset:0;transition:opacity .35s,transform .45s var(--ease)}
.mp-bad{font:12px/24px ui-monospace,monospace;color:#a63d2f;letter-spacing:.06em;transform:rotate(-2deg)}
.mp-good{opacity:0;font-style:italic}.mp-good b{font-weight:400;padding:0 3px;background:linear-gradient(#f2e58a,#f2e58a) no-repeat 0 70%/0% 70%;transition:background-size .45s var(--ease) .15s}
.mp-fig{position:relative;height:56px;border:1.5px dashed #c6c0b0;border-radius:6px;display:grid;place-items:center;transition:border-color .4s}
.mp-missing{font-size:12px;color:#857e6d;transition:opacity .3s}
.mp-chart{position:absolute;inset:8px 10px;width:auto;height:auto;opacity:0;stroke:#3e6b4e;stroke-width:2;transition:opacity .4s}
.mp-ai{position:absolute;top:-8px;right:-6px;font-size:12px;font-weight:600;line-height:1;padding:4px 6px;border-radius:999px;background:#ece8f6;color:#5e4e96;opacity:0;transform:scale(.6);transition:opacity .25s,transform .25s var(--ease)}
.mp-zip{position:absolute;right:10px;bottom:10px;font-size:12px;font-weight:600;padding:5px 8px;border-radius:6px;background:#3e6b4e;color:#fff;transform:translateY(160%);transition:transform .5s var(--ease)}
.mp-scan{position:absolute;left:0;right:0;top:0;height:2px;background:#3e6b4e;box-shadow:0 0 14px 2px #3e6b4e80;opacity:0}
.mini-page.at1:not(.at2) .mp-scan{opacity:1;animation:scan 1.8s linear infinite}
@keyframes scan{to{top:100%}}
.mini-page.at2 .mp-bad{opacity:0;transform:translateY(-6px)}.mini-page.at2 .mp-good{opacity:1}.mini-page.at2 .mp-good b{background-size:100% 70%}
.mini-page.at3 .mp-title{transform:none;background:#3e6b4e}.mini-page.at3 .mp-text{grid-template-columns:1fr 0fr}.mini-page.at3 .mp-text i{transform:none}
.mini-page.at4 .mp-fig{border-style:solid;border-color:#d3cec1}.mini-page.at4 .mp-missing{opacity:0}.mini-page.at4 .mp-chart{opacity:1}.mini-page.at4 .mp-ai{opacity:1;transform:none}
.mini-page.at5 .mp-zip{transform:none}.mini-page.at5{transform:translateY(-4px);box-shadow:0 0 0 1px #00000014,0 18px 34px -12px #141e1460}

/* Reader */
.app-frame>main.result-page{max-width:1240px;margin:0 auto;padding:24px 24px 48px}
.document-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:12px 16px;margin-bottom:20px}
.back-link{display:inline-flex;align-items:center;gap:6px;min-height:44px;padding:0 12px 0 8px;margin-left:-8px;border-radius:10px;font-size:16px;color:var(--ink-2);transition:color .15s}
.document-state{display:flex;align-items:center;flex-wrap:wrap;gap:8px}
.page-nav{display:flex;align-items:center;gap:6px;margin-left:auto;font-size:14px;font-variant-numeric:tabular-nums;color:var(--ink-2)}
.page-nav button{display:grid;place-items:center;width:44px;height:44px;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--ink);transition:transform .12s var(--ease),background-color .15s}
.page-count{min-width:84px;text-align:center}.page-count strong{color:var(--ink);font-weight:600}
.document-workspace{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px;align-items:start}
.reading-surface{min-width:0;background:var(--surface);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow-card);overflow:hidden}
.source-strip{display:flex;align-items:center;flex-wrap:wrap;gap:8px 16px;padding:14px 24px;border-bottom:1px solid var(--line);font-size:14px;color:var(--ink-2)}
.source-file{display:flex;align-items:center;gap:10px;min-width:0}.source-file svg{color:var(--accent);width:20px;height:24px}.source-file strong{color:var(--ink);font-weight:600;overflow-wrap:anywhere}
.source-link{display:inline-flex;align-items:center;gap:6px;min-height:44px;margin-left:auto;color:var(--accent);font-weight:500}.source-link svg{width:16px;height:16px}.source-link:hover{text-decoration:underline;text-underline-offset:3px}
.sample-note{flex-basis:100%;font-size:14px;color:var(--ink-2);margin:-4px 0 0}
.issue-banner{display:flex;gap:12px;align-items:flex-start;margin:20px 24px 0;padding:16px;border-radius:12px;background:var(--warn-soft);color:var(--ink);font-size:16px;line-height:1.5}
.issue-banner>svg{color:var(--warn);width:22px;height:22px;margin-top:1px}.issue-banner strong{display:block;color:var(--warn);font-weight:600}
.issue-banner .chip{margin-top:8px;background:var(--surface);color:var(--warn);white-space:normal}
.issue-banner .button{margin-left:auto;min-height:44px;padding:8px 14px}
.paper-content{max-width:74ch;margin:0 auto;padding:48px 48px 56px;font:19px/1.7 var(--serif);color:var(--ink);overflow-wrap:anywhere}
.paper-content h1{font:600 1.6em/1.25 Geist,system-ui,sans-serif;letter-spacing:-.02em;margin:0 0 20px;text-wrap:balance}
.paper-content h2{font:600 1.2em/1.35 Geist,system-ui,sans-serif;letter-spacing:-.01em;margin:40px 0 14px}
.paper-content h3{font:600 1em/1.45 Geist,system-ui,sans-serif;margin:28px 0 10px}
.paper-content p{margin:0 0 18px}.paper-content strong{font-weight:700}
.paper-content .byline{font:14px/1.7 Geist,system-ui,sans-serif;color:var(--ink-2);margin:4px 0}.paper-content .byline+.paper-block:not(.byline){margin-top:32px}
.paper-content .abstract{padding:20px 22px;border-radius:12px;background:var(--surface-2)}
.paper-content .abstract strong:first-child{display:block;font:600 14px/1.6 Geist,system-ui,sans-serif;color:var(--accent);margin-bottom:6px}
.paper-block{position:relative;scroll-margin:96px}
.paper-equation{overflow:auto;padding:10px 0;margin:0 0 22px;font-size:.9em}.paper-equation .katex-display{margin:.5em 0}.paper-content .katex{font-size:1.04em}.paper-content .katex-display>.katex{white-space:nowrap}
.paper-block.has-issue{padding:34px 14px 8px;border:2px solid var(--warn);border-radius:12px;background:var(--warn-soft)}
.paper-block.has-issue:before{content:attr(data-issue);position:absolute;top:8px;left:14px;font:600 12px/1.4 Geist,system-ui,sans-serif;color:var(--warn)}
.paper-block.has-issue:focus{outline:none}
.paper-content .caption,.paper-content .footnote{font:14px/1.65 Geist,system-ui,sans-serif;color:var(--ink-2)}
.paper-figure{margin:28px 0 32px;border:1px solid var(--line);border-radius:12px;overflow:hidden}
.paper-figure img{display:block;width:100%;height:auto;background:#fff}
.paper-figure figcaption{padding:16px 18px;background:var(--surface-2);font:15px/1.65 Geist,system-ui,sans-serif;color:var(--ink)}
.ai-label{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:10px}.ai-label small{font-size:12px;color:var(--ink-2)}
.paper-table{overflow:auto;margin:20px 0 26px}
.paper-content table{display:table;width:100%;table-layout:auto;border-collapse:collapse;font:14px/1.55 Geist,system-ui,sans-serif}.paper-content tbody{display:table-row-group}.paper-content tr{display:table-row}
.paper-content td,.paper-content th{display:table-cell;padding:10px 12px;border:1px solid var(--line);min-width:70px;vertical-align:top}.paper-content tr:first-child{background:var(--surface-2);font-weight:600}
.paper-content ol{padding-left:26px}.paper-content li{margin:8px 0}.paper-content code{font:.82em ui-monospace,monospace}
.reading-footer{display:flex;align-items:center;flex-wrap:wrap;gap:12px 20px;padding:16px 24px;border-top:1px solid var(--line)}
.feedback{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-left:auto;font-size:14px;color:var(--ink-2)}.feedback>span{margin-right:4px}
.feedback button{display:inline-flex;align-items:center;gap:6px;min-height:44px;padding:0 12px;border:1px solid var(--line);border-radius:10px;color:var(--ink-2);font-size:14px;transition:transform .12s var(--ease),background-color .15s,color .15s}
.feedback button svg{width:18px;height:18px}.feedback button[aria-pressed=true]{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}
.footer-status{flex-basis:100%;text-align:right;font-size:14px;color:var(--ink-2)}.footer-status:empty{display:none}
.result-page>.prototype-note{margin-top:20px}

/* Output rail; becomes a bottom sheet on narrow screens */
.rail{position:sticky;top:72px;max-height:calc(100svh - 88px);overflow-y:auto;scrollbar-width:thin;padding:20px;background:var(--surface);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow-card);font-size:14px;line-height:1.55}
.rail-heading{display:flex;align-items:center;justify-content:space-between;font-size:20px;font-weight:600;line-height:1.3}
.rail-sub{color:var(--ink-2);margin:4px 0 16px}
.rail-actions{display:grid;gap:10px}.rail-actions .button{width:100%}
.text-download{display:inline-flex;align-items:center;justify-content:center;min-height:44px;color:var(--accent);font-weight:500}.text-download:hover,.report-download:hover{text-decoration:underline;text-underline-offset:3px}
.copy-done,.copied .copy-symbol{display:none}.copied .copy-done{display:block}
.output-issue{margin:8px 0 16px;padding:14px;border-radius:12px;background:var(--warn-soft);color:var(--ink)}.output-issue strong{display:block;color:var(--warn);font-size:16px;font-weight:600}.output-issue p{margin:4px 0 8px}
.output-issue button{min-height:44px;color:var(--warn);font-weight:600;text-decoration:underline;text-underline-offset:3px}.output-issue small{display:block;font-size:12px;color:var(--ink-2);margin-top:6px}
.rail details{border-top:1px solid var(--line)}.rail summary{cursor:pointer;list-style:none}.rail summary::-webkit-details-marker{display:none}
.rail>details>summary{position:relative;display:block;padding:16px 32px 16px 0;font-size:16px;font-weight:600}
.rail>details>summary small{display:block;font-size:14px;font-weight:400;color:var(--ink-2);margin-top:2px}
.rail>details>summary:after,.run-stage>summary:after{content:'+';position:absolute;right:4px;top:14px;font-size:20px;font-weight:400;line-height:1.2;color:var(--ink-2);transition:transform .15s var(--ease)}
.rail details[open]>summary:after{transform:rotate(45deg)}
.report-facts{display:grid;grid-template-columns:1fr auto;gap:8px 12px;margin:0 0 14px}.report-facts dt{color:var(--ink-2)}.report-facts dd{margin:0;font-weight:600;font-variant-numeric:tabular-nums}
