export const focusMapNode = (element: HTMLElement): void => Effect.runSync(Effect.sync(() => {
  element.focus({ preventScroll: true })
  element.scrollIntoView({ block: "nearest", inline: "nearest", behavior: "instant" })
}))

export const observeWidth = (element: HTMLElement, onWidth: (width: number) => void): (() => void) => Effect.runSync(Effect.sync(() => {
  const observer = new ResizeObserver((entries) => { const entry = entries[0]; if (entry !== undefined) onWidth(entry.contentRect.width) })
  observer.observe(element)
  return () => Effect.runSync(Effect.sync(() => observer.disconnect()))
}))

const interactiveTargets = "a, button, input, textarea, select, summary, dialog, [contenteditable]"
const plainArrow = (event: KeyboardEvent): boolean =>
  !event.altKey && !event.ctrlKey && !event.metaKey && !event.shiftKey && (event.key === "ArrowLeft" || event.key === "ArrowRight")
const guideKeyHandler = (turn: (delta: number) => void) => (event: KeyboardEvent) => {
  if (!plainArrow(event)) return
  if (event.target instanceof Element && event.target.closest(interactiveTargets)) return
  if (document.querySelector("dialog[open]") !== null) return
  event.preventDefault()
  turn(event.key === "ArrowLeft" ? -1 : 1)
}

export const subscribeGuideKeys = (turn: (delta: number) => void): (() => void) => Effect.runSync(Effect.sync(() => {
  const onKey = guideKeyHandler(turn)
  document.addEventListener("keydown", onKey)
  return () => Effect.runSync(Effect.sync(() => document.removeEventListener("keydown", onKey)))
}))

export const makeRoutePresenter = () => {
  let observedPathname: string | undefined
  let focusPending = true
  const observePathname = (): void => {
    const pathname = window.location.pathname
    if (observedPathname === pathname) return
    observedPathname = pathname
    focusPending = true
  }
  const present = (element: HTMLElement, pathname: string, title: string): void => Effect.runSync(Effect.sync(() => {
    observePathname()
    if (!element.isConnected || window.location.pathname !== pathname) return
    document.title = title
    if (!focusPending) return
    focusPending = false
    element.focus({ preventScroll: true })
  }))
  const subscribe = (listener: () => void): (() => void) => Effect.runSync(Effect.sync(() => {
    observePathname()
    const changed = () => Effect.runSync(Effect.sync(() => { observePathname(); listener() }))
    window.addEventListener("popstate", changed)
    return () => Effect.runSync(Effect.sync(() => window.removeEventListener("popstate", changed)))
  }))
  return { present, subscribe }
}
const routePresenter = makeRoutePresenter()
export const presentRoute = routePresenter.present
export const subscribeLocation = routePresenter.subscribe

export const subscribeClock = (onTick: (now: number) => void): (() => void) => {
  const tick = Clock.currentTimeMillis.pipe(Effect.flatMap((now) => Effect.sync(() => onTick(now))), Effect.andThen(Effect.sleep("1 second")))
  const interrupt = Effect.runCallback(Effect.forever(tick))
  return () => interrupt()
}

export const afterDelay = (delay: Duration.Input, run: () => void): (() => void) => {
  const interrupt = Effect.runCallback(Effect.sleep(delay).pipe(Effect.andThen(Effect.sync(run))))
  return () => interrupt()
}

export const openProcessingReport =(details: HTMLDetailsElement, summary: HTMLElement): void => Effect.runSync(Effect.sync(() => {
  details.open = true
  summary.focus({ preventScroll: true })
  summary.scrollIntoView({ block: "start", behavior: "instant" })
}))

const body = yield* Schema.decodeUnknownEffect(RetryRequest)(input, boundaryParseOptions).pipe(Effect.mapError(unpreparedRetry))
const request = yield* HttpClientRequest.post(productRoutes.retry.path.replace(":documentId", id)).pipe(
  HttpClientRequest.setHeader("idempotency-key", key), HttpClientRequest.bodyJson(body), Effect.mapError(transport),
)

if (accepted.documentId !== id || accepted.runId === input.previousRunId) {
  return yield* new DocumentFailure({ kind: "invalid-response", message: unconfirmedRetry })
}

const mismatch = invalid(unreadableOutput)
const readJson = <A>(url: string, schema: Schema.Decoder<A>) => requestJson(HttpClientRequest.get(url), schema, 200)

const sameRevision = (identity: OutputIdentity, canonical: CanonicalDocument, report: ProcessingReport): boolean =>
  canonical.scope.documentId === identity.documentId && canonical.scope.revisionId === identity.revisionId
  && report.scope.documentId === identity.documentId && report.scope.revisionId === identity.revisionId && report.scope.runId === canonical.scope.runId
const acceptedGuideReceipt = (identity: OutputIdentity, canonical: CanonicalDocument, report: ProcessingReport): boolean => {
  const guide = canonical.guide
  if (guide === undefined) return true
  const receipt = report.receipts.find((item) => item.receipt.id === guide.providerAttemptId)?.receipt
  return validGuideSources(guide, canonical.sourceBlocks) && receipt?.stage === "guide" && receipt.scope.documentId === identity.documentId
    && receipt.scope.sourceHash === canonical.sourceHash && receipt.state._tag === "completed" && receipt.state.validation._tag === "accepted"
}

export const readPublishedDocument = Effect.fn("readPublishedDocument")(function* (identity: OutputIdentity) {
  const [canonical, report] = yield* Effect.all([
    readJson(outputUrl(identity, "canonical"), productRoutes.canonical.response),
    readJson(outputUrl(identity, "report"), productRoutes.report.response),
  ], { concurrency: 2 })
  if (!sameRevision(identity, canonical, report)) return yield* mismatch("Output revision mismatch")
  if (!acceptedGuideReceipt(identity, canonical, report)) return yield* mismatch("Reading guide evidence or receipt mismatch")
  return { canonical, report }
})

const response = yield* respond(HttpClientRequest.get(outputUrl(identity, "text")), 200)
if (!response.headers["content-type"]?.toLowerCase().startsWith("text/plain")) return yield* mismatch("Expected normalized text")
return yield* response.text.pipe(Effect.mapError(mismatch))

const clipboardFailure = (cause: unknown) =>
  new DocumentFailure({ kind: "rejected", message: "Your browser could not copy the text. Download the text file instead.", cause })
const clipboardDeadline = Effect.timeoutOrElse({
  duration: "10 seconds",
  orElse: () => Effect.fail(new DocumentFailure({ kind: "rejected", message: "Copying took too long. Download the text file instead." })),
})

export const stageLabels: Record<typeof Stage.Type, { readonly name: string; readonly progress: string }> = {
  extraction: { name: "Extract document", progress: "Extracting pages" },
  "page-check": { name: "Check pages", progress: "Checking pages" },
  headings: { name: "Restore headings", progress: "Restoring headings" },
  figures: { name: "Describe figures", progress: "Describing figures" },
  assembly: { name: "Assemble document", progress: "Assembling the document" },
  guide: { name: "Prepare reading guide", progress: "Preparing your reading guide" },
  export: { name: "Prepare downloads", progress: "Preparing downloads" },
}

type Progress = Extract<Run["state"], { readonly _tag: "running" }>["progress"]
const stageOrder: ReadonlyArray<typeof Stage.Type> = ["extraction", "page-check", "headings", "figures", "assembly", "guide", "export"]
const plainStages: Record<typeof Stage.Type, { readonly step: string; readonly now: string; readonly unit?: string }> = {
  extraction: { step: "Read every page", now: "Muse is reading", unit: "page" },
  "page-check": { step: "Check each page against the original", now: "Muse is checking", unit: "page" },
  headings: { step: "Restore the headings", now: "Muse is restoring the headings" },
  figures: { step: "Describe the figures", now: "Muse is describing", unit: "figure" },
  assembly: { step: "Assemble the clean copy", now: "Assembling your clean copy" },
  guide: { step: "Write the reading guide", now: "Muse is writing your reading guide" },
  export: { step: "Prepare downloads", now: "Preparing your downloads" },
}

export const progressHeadline = ({ stage, completedUnits, totalUnits }: Progress): string => {
  const { now, unit } = plainStages[stage]
  if (unit === undefined) return now
  if (totalUnits === null || totalUnits === 0) return stage === "figures" ? "Looking for figures to describe" : `${now} the ${unit}s`
  if (completedUnits >= totalUnits) return `${now} the ${unit}s · all ${totalUnits} done`
  return `${now} ${unit} ${completedUnits + 1} of ${totalUnits}`
}

export type ProcessingStep = { readonly stage: typeof Stage.Type; readonly label: string; readonly state: "done" | "now" | "next"; readonly detail: string | null }
export const processingSteps = (run: Pick<Run, "state" | "configuration">): ReadonlyArray<ProcessingStep> => {
  const state = run.state
  const current = state._tag === "running" ? stageOrder.indexOf(state.progress.stage) : -1
  return stageOrder.filter((stage) => stage !== "guide" || run.configuration.guide !== undefined || (state._tag === "running" && state.progress.stage === "guide"))
    .map((stage) => {
      const index = stageOrder.indexOf(stage)
      const now = state._tag === "running" && index === current
      const detail = now && state.progress.totalUnits !== null && state.progress.totalUnits > 0
        ? `${state.progress.completedUnits} of ${state.progress.totalUnits} done` : null
      return { stage, label: plainStages[stage].step, state: index < current ? "done" : now ? "now" : "next", detail }
    })
}

export const elapsedLabel = (startedAt: string, now: number): string | null => {
  const started = Date.parse(startedAt)
  if (!Number.isFinite(started) || now < started) return null
  const seconds = Math.floor((now - started) / 1000)
  const minutes = Math.floor(seconds / 60)
  if (minutes >= 60) return `${Math.floor(minutes / 60)} h ${String(minutes % 60).padStart(2, "0")} min`
  return minutes === 0 ? `${seconds} s` : `${minutes} min ${String(seconds % 60).padStart(2, "0")} s`
}

const longDocument = "This document is longer than one AmuseMe run can cover. Try a shorter PDF or an excerpt of a few pages. The original stays here to read."
export const failureCopy = (failure: { readonly code: string; readonly message: string }): { readonly title: string; readonly description: string } | null => {
  if (failure.code === "limit-exceeded") return { title: "This document is too long for one run", description: longDocument }
  return null
}

export const processingEstimate =
  "This usually takes several minutes. You can leave this page; your guide will be in your library when it’s ready."

type RunSummary = { readonly title: string; readonly description: string; readonly failed: boolean }
export const runSummary = (run: Pick<Run, "state">): RunSummary => {

case "queued": return { title: "Waiting for Muse to start", description: "Your document is saved and next in line.", failed: false }
case "running": return { title: progressHeadline(state.progress), description: processingEstimate, failed: false }
case "failed": return { ...failureCopy(state.failure) ?? { title: "Processing stopped", description: state.failure.message }, failed: true }
case "interrupted": return { ...failureCopy(state.failure) ?? { title: "Processing interrupted", description: state.failure.message }, failed: true }
case "succeeded": return { title: "Processing complete", description: "Your clean copy is ready to read and download.", failed: false }
case "succeeded-with-issues": return { title: "Completed with issues", description: "Your clean copy is ready. Review the reported issues before using it.", failed: false }

export const safeReturnPath = (value: string | null): string => {
  if (value === null) return "/"
  const [path, query] = value.split("?")
  if (!Schema.is(ReturnPath)(path)) return "/"
  if (query === undefined) return value
  return path !== "/" && value.split("?").length === 2 && validDocumentQuery(query) ? value : "/"
}

export const parseLocation = (location: string) => {
  const [pathname = "", search = ""] = location.split("?")
  const params = new URLSearchParams(search)
  return { location, pathname, route: routeFromParts(pathname, params), ...documentQuery(params) }
}

export const routeFromLocation = (location: string): AppRoute => parseLocation(location).route

