      Effect.succeed(
        row.status === "dispatching" || row.status === "submitted"
          ? {
              status: "unknown",
              receipt_json: JSON.stringify({
                ...receipt,
                state: { _tag: "unknown-completion", observedAt: timestamp(now), providerRequestId: row.remote_id, reason },
              }),
            }
          : {},
      ),
    false,
  ).pipe(Effect.asVoid)
const validateSaved = Effect.fn("ProviderGuard.validateSaved")(function* (
  claim: DispatchClaim,
  result: GuardedResponse,
  expected: ReceiptExpectation,
) {

const row = yield* database.query("provider-validation", () =>
  database.db.selectFrom("provider_attempts").selectAll().where("id", "=", result.receipt.id).executeTakeFirst(),
)
if (row === undefined || row.owner_id !== claim.run.ownerId || row.document_id !== claim.document.id || row.status !== "completed")
  return yield* invalidStored()

if (
  new TextEncoder().encode(json(saved.response)).length > intent.maxResponseBytes ||
  (receipt.state._tag === "completed" &&
    receipt.state.usage._tag === "reported" &&
    receipt.state.usage.outputTokens !== null &&
    intent.maxOutputTokens !== null &&
    receipt.state.usage.outputTokens > intent.maxOutputTokens)
)
  return yield* executionFailure("limit-exceeded", "The provider response exceeds its configured output limit")
if (row.actual_microusd !== null && row.actual_microusd > intent.maximumCostMicrousd)
  return yield* executionFailure("limit-exceeded", "The provider charge exceeded its reserved maximum")

const validation = yield* Effect.result(
  validate.pipe(
    Effect.timeoutOrElse({
      duration: policy.callDeadlineMilliseconds,
      orElse: () => Effect.fail(executionFailure("provider-failed", "Local response validation exceeded its deadline")),
    }),
  ),
)

const accepted = yield* database.transaction((db) =>
  Effect.gen(function* () {
    const now = yield* Clock.currentTimeMillis
    yield* assertClaim(db, claim, now)
    const state = receipt.state
    if (state._tag !== "completed") return yield* invalidStored()
    const updated: StageReceipt = {
      ...receipt,
      state: { ...state, validation: validation._tag === "Success" ? { _tag: "accepted" } : rejected(validation.failure.message) },
    }
    const changed = yield* database.query("provider-validation", () =>
      db
        .updateTable("provider_attempts")
        .set({
          validation_state: validation._tag === "Success" ? "accepted" : "rejected",
          receipt_json: JSON.stringify(updated),
          updated_at: now,
        })
        .where("id", "=", row.id)
        .where("response_json", "=", row.response_json)
        .where("receipt_json", "=", row.receipt_json)
        .where("validation_state", "=", row.validation_state)
        .executeTakeFirst(),
    )
    if (changed.numUpdatedRows !== 1n)
      return yield* executionFailure("conflict", "The saved provider response changed during validation")
    return updated
  }),
)

const complete = Effect.fn("ProviderGuard.complete")(function* (
  ticket: AttemptTicket,
  response: ProviderResponse,
  allowed: ReadonlyArray<string>,
) {

const responseHash = yield* hash(responseJson).pipe(
  Effect.flatMap(Schema.decodeUnknownEffect(ArtifactHash)),
  Effect.mapError(invalidStored),
)
const raw = yield* mutate(
  ticket,
  (row, receipt, now) => {
    if (!allowed.includes(row.status))
      return Effect.fail(executionFailure("conflict", "The provider result arrived after its attempt stopped"))
    return Effect.succeed({
      status: "completed",
      validation_state: "pending",
      response_json: responseJson,
      actual_microusd: chargedMicrousd(policy, receipt.configuration, response),
      receipt_json: JSON.stringify({
        ...receipt,
        state: {
          _tag: "completed",
          finishedAt: timestamp(now),
          providerRequestId: row.remote_id,
          responseHash,
          durationMilliseconds: now - (row.dispatch_started_at ?? now),
          usage: response.usage,
          validation: rejected("The saved response has not passed stage validation"),
        },
      }),
    })
  },
  false,
)

return yield* validateSaved(
  ticket.claim,
  { delivery: receipt.scope.runId === ticket.claim.run.id ? "performed" : "reused", receipt, response: response.response },
  ticket.receipt,
)

const dispatch = Effect.fn("ProviderGuard.dispatch")(function* (
  ticket: AttemptTicket,
): Effect.fn.Return<GuardedResponse, GuardError, ProviderAdapter> {

const started = yield* mutate(
  ticket,
  (row, receipt, now) => {
    if (
      policy.mode === "live" &&
      (!metaRuntimeConfiguration(ticket.claim.run.configuration) || receipt.configuration.provider !== "meta")
    )
      return Effect.fail(executionFailure("processing-unavailable", "This runtime permits only Meta model dispatch"))
    return row.status !== "prepared" || row.lease_expires_at <= now
      ? Effect.fail(executionFailure("provider-unknown-completion", "This provider attempt cannot be dispatched again"))
      : Effect.succeed({ status: "dispatching", dispatch_started_at: now })
  },
  true,
)

const submitted = (providerRequestId: string) =>
  Schema.decodeUnknownEffect(Schema.String.check(Schema.isMinLength(1), Schema.isMaxLength(512)))(providerRequestId).pipe(
    Effect.mapError(() => executionFailure("invalid-provider-response", "The provider request ID is invalid")),
    Effect.flatMap((remoteId) =>
      mutate(
        ticket,
        (row, receipt, now) => {
          if (row.remote_id !== null && row.remote_id !== remoteId)
            return Effect.fail(executionFailure("conflict", "The provider request ID changed"))
          if (!["dispatching", "submitted", "unknown"].includes(row.status))
            return Effect.fail(executionFailure("conflict", "The provider attempt is already terminal"))
          return Effect.succeed({
            status: "submitted",
            remote_id: remoteId,
            receipt_json: JSON.stringify({
              ...receipt,
              state: { _tag: "submitted", submittedAt: timestamp(now), providerRequestId: remoteId },
            }),
          })
        },
        false,
      ),
    ),
    Effect.asVoid,
  )

Effect.timeoutOrElse({
  duration: Math.max(0, intent.deadlineAt - now),
  orElse: () =>
    Effect.fail(executionFailure("provider-unknown-completion", "The provider deadline elapsed; remote completion is unknown")),
}),
Effect.onExit((exit) =>
  Exit.isFailure(exit) ? unknown(ticket, "Execution ended without a durable accepted response") : Effect.void,
),

const response = yield* get(ticket.receipt).pipe(
  Effect.catchTag("ProviderFailure", () =>
    Effect.fail(executionFailure("provider-unknown-completion", "The existing extraction job could not be retrieved")),
  ),
  Effect.flatMap(Schema.decodeUnknownEffect(ProviderResponse)),
  Effect.mapError((error) => (error._tag === "SchemaError" ? invalidStored() : error)),
)

}).pipe(
  Effect.timeoutOrElse({
    duration: Math.max(0, ticket.intent.deadlineAt - now),
    orElse: () =>
      Effect.fail(executionFailure("provider-unknown-completion", "Retrieval deadline elapsed; the original job remains unresolved")),
  }),
)

}, slots.withPermit)
const savedRejection = Effect.fn("ProviderGuard.rejected")(function* (claim: DispatchClaim, raw: AttemptInput) {
  const input = yield* Schema.decodeUnknownEffect(AttemptInput)(raw, { onExcessProperty: "error" }).pipe(Effect.mapError(invalidStored))
  const stageSettings = stageConfiguration(claim.run.configuration, input.stage)
  if (stageSettings === undefined) return null
  const fingerprint = yield* fingerprintOf(claim.run, claim.document, input, stageSettings)
  const stageKey = providerUnitKey(input)
  const row = yield* database.query("provider-rejected", () =>
    database.db
      .selectFrom("provider_attempts")
      .selectAll()
      .where("owner_id", "=", claim.document.ownerId)
      .where("document_id", "=", claim.document.id)
      .where("stage_key", "=", stageKey)
      .where("fingerprint", "=", fingerprint)
      .where("status", "=", "completed")
      .where("validation_state", "=", "rejected")
      .orderBy("created_at", "desc")
      .executeTakeFirst(),
  )
  if (row === undefined) return null
  const expected: ReceiptExpectation = {
    ownerId: claim.run.ownerId,
    scope: { documentId: claim.document.id, runId: claim.run.id, sourceHash: claim.document.sourceHash },
    pipelineVersion: claim.run.pipelineVersion,
    schemaVersion: claim.run.schemaVersion,
    requestFingerprint: fingerprint,
    stage: input.stage,
    pageIds: input.pageIds,
    figureId: input.figureId,
    ...(input.task === undefined ? {} : { task: input.task }),
    configuration: stageSettings,
    inputHashes: input.inputHashes,
  }
  const receipt = yield* decodeReceipt(row).pipe(Effect.flatMap((saved) => checkExpectedReceipt(saved, expected)))
  if (receipt.state._tag !== "completed" || receipt.state.validation._tag !== "rejected" || row.response_json === null)
    return yield* invalidStored()
  const response = yield* Schema.decodeUnknownEffect(Schema.fromJsonString(Schema.Json))(row.response_json).pipe(
    Effect.mapError(invalidStored),
  )
  if ((yield* hash(json(response))) !== receipt.state.responseHash) return yield* invalidStored()
  return { delivery: receipt.scope.runId === claim.run.id ? ("performed" as const) : ("reused" as const), receipt, response }

return yield* database.transaction((db) =>
  Effect.gen(function* () {
    const now = yield* Clock.currentTimeMillis
    const rows = yield* database.query("provider-reconcile", () =>
      db
        .selectFrom("provider_attempts")
        .selectAll()
        .where("status", "in", ["dispatching", "submitted"])
        .where("lease_expires_at", "<=", now)
        .execute(),
    )
    for (const row of rows) {
      const receipt = yield* decodeReceipt(row)
      yield* database.query("provider-reconcile", () =>
        db
          .updateTable("provider_attempts")
          .set({
            status: "unknown",
            updated_at: now,
            receipt_json: JSON.stringify({
              ...receipt,
              state: {
                _tag: "unknown-completion",
                observedAt: timestamp(now),
                providerRequestId: row.remote_id,
                reason: "The worker stopped before saving a response",
              },
            }),
          })
          .where("id", "=", row.id)
          .execute(),
      )
    }
    return rows.length
  }),
)

export class NormalizationStages extends Context.Service<
  NormalizationStages,
  {
    readonly execute: (claim: DispatchClaim, stage: typeof Stage.Type, input: Checkpoint) => Effect.Effect<Checkpoint, WorkflowStageFailure>
  }
>()("amuseme/processing/NormalizationStages") {
  static readonly layer = (meta: ReturnType<typeof makeMetaAgentBoundary>, options?: PipelineOptions) =>
    Layer.effect(
      NormalizationStages,
      Effect.gen(function* () {
        if (options === undefined) {
          const message = "Document processing is not configured"
          const failure = { code: "processing-unavailable", message, retryable: false, stage: null, pageId: null, figureId: null } as const
          return NormalizationStages.of({ execute: () => Effect.fail(new WorkflowStageFailure({ failure })) })
        }
        const context = yield* makeStageContext(meta, options)
        const { documents } = context
        const review = makeMuseReview(context)
        const crops = makeFigureCrops(context)
        const extract = makeExtract(context, review, crops)
        const checkPages = makeCheckPages(context, review)
        const classifyHeadings = makeClassifyHeadings(context, review)
        const describeFigures = makeDescribeFigures(context, review)
        const assemble = makeAssemble(context)
        const writeGuide = makeWriteGuide(context, review)
        const exportAndPublish = makeExportAndPublish(context)
        const stageHandlers = {
          extraction: extract,
          "page-check": checkPages,
          headings: classifyHeadings,
          figures: describeFigures,
          assembly: assemble,
          guide: writeGuide,
          export: exportAndPublish,
        } satisfies Record<typeof Stage.Type, StageHandler>

        const execute = Effect.fn("NormalizationStages.execute")(
          function* (claim: DispatchClaim, stage: typeof Stage.Type, input: Checkpoint) {
            if (!metaRuntimeConfiguration(claim.run.configuration)) {
              return yield* executionFailure(
                "processing-unavailable",
                "This runtime permits only Meta model processing; historical non-Meta outputs remain readable",
              )
            }
            if (input.documentId !== claim.document.id || input.runId !== claim.run.id) {
              return yield* executionFailure("conflict", "The workflow checkpoint belongs to another run")
            }
            const savedDocument = yield* documents.detail(claim.document.ownerId, claim.document.id)
            if (savedDocument.latestRun.id !== claim.run.id || !metaRuntimeConfiguration(savedDocument.latestRun.configuration)) {
              return yield* executionFailure("processing-unavailable", "The saved run is not eligible for this Meta-only runtime")
            }
            return yield* stageHandlers[stage](claim, input)
          },
          (effect, _claim, stage) =>
            effect.pipe(Effect.mapError((error) => new WorkflowStageFailure({ failure: stageFailure(error, stage) }))),
        )
        return NormalizationStages.of({ execute })
      }),
    )

import type { ProviderStage, ProviderTask, RunConfiguration, Usage, StageReceipt } from "../domain/index.ts"
import { GuardPolicy, type ProviderResponse, type AttemptInput } from "./contracts.ts"

export const runGuardPolicy = (policy: GuardPolicy, configuration: typeof RunConfiguration.Type): GuardPolicy => {
  if (configuration.guide !== undefined || policy.maximumCostMicrousd.guide === undefined) return policy
  const { guide: _guide, ...maximumCostMicrousd } = policy.maximumCostMicrousd
  return { ...policy, maximumCostMicrousd }
}

if (!policy.metaCredentialConfigured) return { available: false, reason: "Processing credentials are not configured" }
if (
  policy.authorizedBudgetMicrousd === null ||
  policy.authorizedBudgetMicrousd <= 0 ||
  Object.values(policy.maximumCostMicrousd).some((cost) => cost <= 0)
)
  return { available: false, reason: "An authorized budget and worst-case provider charges are required" }

export const metaRuntimeConfiguration = (configuration: typeof RunConfiguration.Type): boolean =>
  configuration.extractionProvider === "meta" &&
  configuration.extractionVersion === museSparkModel &&
  isMuseModel(configuration.extractionModel) &&
  [
    configuration.pageCheck,
    configuration.headings,
    configuration.figures,
    ...(configuration.guide === undefined ? [] : [configuration.guide]),
  ].every(isMuseModel)

export const stageReservation = (
  policy: GuardPolicy,
  stage: typeof ProviderStage.Type,
  task?: typeof ProviderTask.Type,
): number | undefined =>
  task === "figure-crop"
    ? (policy.maximumCostMicrousd["figure-crop"] ?? policy.maximumCostMicrousd.figures)
    : policy.maximumCostMicrousd[stage]

type Configuration = typeof RunConfiguration.Type
const spendingCapMicrousd = (configuration: Configuration) => Math.floor(configuration.spendingCapUsd * 1_000_000)
const pageReservation = ({ maximumCostMicrousd: cost }: GuardPolicy) => cost.extraction + cost["page-check"]

export const minimumReservationMicrousd = (policy: GuardPolicy, configuration: Configuration, pageCount: number): number | undefined => {
  const guide = configuration.guide === undefined ? 0 : policy.maximumCostMicrousd.guide
  if (guide === undefined) return undefined
  return pageCount * pageReservation(policy) + policy.maximumCostMicrousd.headings + guide
}

export const affordablePageLimit = (policy: GuardPolicy, configuration: Configuration): number => {
  const fixed = minimumReservationMicrousd(policy, configuration, 0)
  const cap = spendingCapMicrousd(configuration)
  if (fixed === undefined || !Number.isSafeInteger(fixed) || fixed > cap) return 0
  const perPage = pageReservation(policy)
  return perPage === 0 ? Number.POSITIVE_INFINITY : Math.floor((cap - fixed) / perPage)
}

const metaTokenMicrousd = (rates: NonNullable<GuardPolicy["metaRates"]>, inputTokens: number, outputTokens: number): number =>
  Math.ceil((inputTokens * rates.inputMicrousdPerMillionTokens + outputTokens * rates.outputMicrousdPerMillionTokens) / 1_000_000)

export const metaWorstCaseMicrousd = (rates: NonNullable<GuardPolicy["metaRates"]>, inputTokens: number, maxOutputTokens: number): number =>
  metaTokenMicrousd(rates, inputTokens, maxOutputTokens)

export const metaMeteredMicrousd = (rates: NonNullable<GuardPolicy["metaRates"]>, usage: typeof Usage.Type): number | null =>
  usage._tag === "reported" && usage.inputTokens !== null && usage.outputTokens !== null
    ? metaTokenMicrousd(rates, usage.inputTokens, usage.outputTokens)
    : null

export const remainingHeadroomMicrousd = (reservations: ReadonlyArray<number>, charged: ReadonlyArray<number> = []): number =>
  Math.max(
    0,
    charged.reduce(
      (remaining, cost) => remaining - cost,
      reservations.reduce((sum, cost) => sum + cost, 0),
    ),
  )

export const museSparkRates = {
  inputMicrousdPerMillionTokens: 1_250_000,
  outputMicrousdPerMillionTokens: 4_250_000,
} as const

export const stageReservations = {
  extraction: 300_000,
  "page-check": 300_000,
  headings: 500_000,
  figures: 500_000,
  guide: 500_000,
  "figure-crop": 200_000,
} as const

export const exceedsStageReservation = (
  policy: GuardPolicy,
  input: AttemptInput,
  maxOutputTokens: number | null,
  reserved: number,
): boolean =>
  policy.metaRates !== undefined &&
  input.inputTokenBound !== undefined &&
  metaWorstCaseMicrousd(policy.metaRates, input.inputTokenBound, maxOutputTokens ?? policy.maxOutputTokens) > reserved

export const chargedMicrousd = (
  policy: GuardPolicy,
  configuration: StageReceipt["configuration"],
  response: ProviderResponse,
): number | null => {
  const metered =
    policy.metaRates !== undefined && configuration.provider === "meta" ? metaMeteredMicrousd(policy.metaRates, response.usage) : null
  return response.actualCostMicrousd ?? metered
}

if (json(receipt.configuration) !== json(expectedConfiguration) || intent.maxOutputTokens !== maxOutputTokens || maxOutputTokens !== null && maxOutputTokens > policy.maxOutputTokens || intent.maxResponseBytes !== policy.maxResponseBytes || intent.maximumCostMicrousd !== stageReservation(policy, receipt.stage, receipt.task) || row.reserved_microusd !== intent.maximumCostMicrousd || intent.clientIdempotencyKey !== null && intent.clientIdempotencyKey !== receipt.id) return yield* invalid()
const fingerprint = yield* requestFingerprint({
  run, document, unit: receipt, configuration: receipt.configuration, request: intent.request,
  supportsIdempotency: intent.clientIdempotencyKey !== null, policy,
}).pipe(Effect.provideService(Crypto.Crypto, crypto), Effect.mapError(invalid))

const optionalSetting = <A>(schema: Schema.Codec<A, string>, name: string) => Config.String(name).pipe(Config.option, Effect.flatMap((value) =>
  Option.isNone(value) || value.value.trim() === "" ? Effect.succeed(undefined) : Schema.decodeUnknownEffect(schema)(value.value.trim())))
const optionalText = (name: string) => Config.schema(Schema.Redacted(Schema.String), name).pipe(Config.option, Config.map(Option.filter((value) => Redacted.value(value) !== "")))

const origin = yield* Config.schema(Origin.check(Schema.makeFilter((value) => value.startsWith("https:") || Number(new URL(value).port || "80") === port || "Origin port must match AMUSEME_PORT")), "AMUSEME_ORIGIN").pipe(Config.withDefault(`http://127.0.0.1:${port}`))
const Host = Schema.Literals(["127.0.0.1", "0.0.0.0"]).check(Schema.makeFilter((value) =>
  value === "127.0.0.1" || origin.startsWith("https:")
  || "AMUSEME_HOST=0.0.0.0 needs an https:// AMUSEME_ORIGIN served through a TLS-terminating proxy."
  + " Use 127.0.0.1 for plain HTTP"))
const host = yield* Config.schema(Host, "AMUSEME_HOST").pipe(Config.withDefault("127.0.0.1" as const))
