  })
}

const { ownerId: owner } = yield* documentReadPolicy(store, session.user.id, id)
if (operation === "detail") return yield* jsonResponse(DocumentDetail, yield* store.detail(owner, id))
if (operation === "status") return yield* jsonResponse(Run, yield* store.status(owner, id))
if (operation === "preview") return yield* previews.renderPage(owner, id, new URL(request.url).searchParams.get("page"), request.signal)
