it.effect("guards Muse review attempts and retries only the unresolved review after unknown completion", () => Effect.gen(function* () {
  const settings = yield* options
  let calls = 0
  const reviewed = { ...response, response: { text: "Reviewed response" } }
  const invoke: ProviderAdapter["Service"]["invoke"] = (call) => Effect.suspend(() => {
    calls += 1
    if (call.intent.retry._tag === "none") return Effect.succeed(response)
    return calls === 2 ? unknown() : Effect.succeed(reviewed)
  })
  yield* Effect.gen(function* () {
    const first = yield* admitted({ attempts: 5 })
    const guard = yield* ProviderGuard
    const original = yield* input()
    expect(yield* Effect.result(guard.execute(first, original))).toMatchObject({ _tag: "Failure", failure: { code: "invalid-provider-response" } })
    const saved = yield* guard.rejected(first, original)
    if (saved === null) return yield* Effect.die("Expected the saved rejected answer")
    expect(saved).toMatchObject({ delivery: "performed", response: response.response })
    const review = (headroomMicrousd = 0, previousAttemptId: string = saved.receipt.id) => Schema.decodeUnknownEffect(AttemptInput)({ ...original, request: { page: "page-1", text: "Retained text", museReview: 1 }, retry: { _tag: "review", previousAttemptId, round: 1, headroomMicrousd } })
    expect(yield* Effect.result(guard.execute(first, yield* review(10_000_000)))).toMatchObject({ _tag: "Failure", failure: { code: "limit-exceeded" } })
    expect(yield* Effect.result(guard.execute(first, yield* review(0, "00000000-0000-4000-8000-000000000000")))).toMatchObject({ _tag: "Failure", failure: { code: "conflict" } })
    expect(yield* Effect.result(guard.execute(first, yield* review()))).toMatchObject({ _tag: "Failure", failure: { code: "provider-unknown-completion" } })
    expect(calls).toBe(2)
    yield* stop(first)
    yield* (yield* RunRecovery).requestRetry(yield* retryRequest(first))
    const second = yield* next()
    expect((yield* guard.retryInput(second, original)).retry._tag).toBe("none")
    expect(yield* Effect.result(guard.execute(second, original))).toMatchObject({ _tag: "Failure", failure: { code: "invalid-provider-response" } })
    expect((yield* guard.rejected(second, original))?.receipt.id).toBe(saved.receipt.id)
    const corrected = yield* guard.execute(second, yield* review())
    expect(corrected).toMatchObject({ delivery: "performed", response: reviewed.response })
    expect((yield* guard.execute(second, yield* review())).receipt.id).toBe(corrected.receipt.id)
    expect(calls).toBe(3)
    expect((yield* attempts).map((row) => [row.status, row.validation_state])).toEqual([["completed", "rejected"], ["unknown", null], ["completed", "accepted"]])
  }).pipe(Effect.provide(Layer.merge(layer(settings), adapter(invoke, acceptReviewed))))

